//! Wire protocol constants of the extension <-> bridge link.
//!
//! Data only: no logic. `bridge/protocol.mjs` and `extension/protocol.js` carry
//! the same values twice (a MV3 background script cannot import an ES module), and
//! `tests/protocol.rs` is what keeps the third copy honest.
//!
//! The one function below — `constants()` — is the third copy handed to that test
//! and generated by the same macro as the constants themselves, so the comparison
//! cannot fall behind a constant someone forgot to list.

/// Declares the wire constants and, from the same source, the `(path, value)`
/// table the protocol test compares with `extension/protocol.js`.
///
/// A hand-maintained table is the failure this replaces: a new constant added to
/// the module without an entry in the test's list would leave every case green and
/// the extension free to disagree. Here a constant that is not declared is not
/// compiled, so there is nothing to forget.
///
/// The item grammar is explicit rather than inferred from the Rust declaration
/// (`$name:ident : $ty:ty = $value:expr`), because the table needs the value, and
/// `macro_rules!` can only stringify what it can name. `flat { … }` holds the
/// top-level constants; every `group <mod> as <PATH>` becomes a `pub mod <mod>`
/// whose constants are listed under `<PATH>` — the spelling the extension's object
/// uses. The two names are separate because a Rust module must be snake case while
/// the wire path is not: `group types as TYPES { HELLO: &str = "hello"; }` yields
/// `protocol::types::HELLO` and the pair `("TYPES.HELLO", "hello")`.
macro_rules! protocol_constants {
    (
        flat {
            $( $(#[$flat_doc:meta])* $flat_name:ident : $flat_ty:ty = $flat_value:expr ; )*
        }
        $(
            $(#[$group_doc:meta])*
            group $group:ident as $wire_group:ident {
                $( $(#[$member_doc:meta])* $member:ident : $member_ty:ty = $member_value:expr ; )*
            }
        )*
    ) => {
        $(
            $(#[$flat_doc])*
            pub const $flat_name: $flat_ty = $flat_value;
        )*

        $(
            $(#[$group_doc])*
            pub mod $group {
                $(
                    $(#[$member_doc])*
                    pub const $member: $member_ty = $member_value;
                )*
            }
        )*

        /// Every constant above, as the dotted path the extension's copy uses for
        /// it and its value as a string. Generated by the macro, so the list is
        /// complete by construction; `tests/protocol.rs` compares it with
        /// `extension/protocol.js` entry by entry.
        pub fn constants() -> Vec<(String, String)> {
            vec![
                $(
                    (stringify!($flat_name).to_string(), $flat_name.to_string()),
                )*
                $(
                    $(
                        (
                            format!("{}.{}", stringify!($wire_group), stringify!($member)),
                            $group::$member.to_string(),
                        ),
                    )*
                )*
            ]
        }
    };
}

protocol_constants! {
    flat {
        /// The protocol generation the `hello` handshake must agree on.
        VERSION: u32 = 1;

        /// The frame-size ceiling. A frame that announces more is refused before
        /// its payload is buffered, which is why the number is a constant and not
        /// a default.
        MAX_MESSAGE_BYTES: usize = 5_242_880;

        /// How long the extension may take between the upgrade and its `hello`.
        HELLO_TIMEOUT_MS: u64 = 5_000;

        /// How long one tool call may take before the bridge answers
        /// `ExtensionTimeout`.
        CALL_TIMEOUT_MS: u64 = 20_000;

        /// The budget of one injected call's answers (spec 45). Its own number and
        /// not `CALL_TIMEOUT_MS`: a page deadline of the same length would fire
        /// together with the bridge's patience, and the agent would see
        /// `ExtensionTimeout` instead of the tool's own answer.
        ///
        /// The mirror was missing since spec 45 stage 1a — the extension carried the
        /// constant and this table did not, which is exactly the drift this test exists
        /// for. Found while adding the farewell type (spec 44).
        INJECTION_REPLY_TIMEOUT_MS: u64 = 5_000;

        /// Reconnect backoff of the extension, kept here because it is
        /// wire-adjacent timing that both sides read from the same table.
        RECONNECT_BASE_MS: u64 = 1_000;
        RECONNECT_MAX_MS: u64 = 30_000;
        RECONNECT_JITTER_MS: u64 = 250;
    }

    /// Frame types of the link.
    group types as TYPES {
        HELLO: &str = "hello";
        WELCOME: &str = "welcome";
        REQUEST: &str = "request";
        RESPONSE: &str = "response";
        /// The extension's farewell on a switch-off (spec 44). Received and
        /// deliberately ignored — `hub.rs` drops every type but `response`, and the
        /// reaction belongs to roadmap 32, not to this increment.
        GOODBYE: &str = "goodbye";
    }

    /// Methods the extension answers in this increment. Anything else is replied
    /// to with `ok:false, code:"unsupported_method"` rather than silently ignored.
    group methods as METHODS {
        STATUS: &str = "status";
        NAVIGATE: &str = "navigate";
        READ: &str = "read";
        CLICK: &str = "click";
        TYPE: &str = "type";
        FOCUS: &str = "focus";
        INSPECT: &str = "inspect";
        OPEN_TAB: &str = "open_tab";
        CLOSE_TAB: &str = "close_tab";
        EVAL: &str = "eval";
        SCREENSHOT: &str = "screenshot";
        FRAMES: &str = "frames";
        TRANSCRIPT: &str = "transcript";
    }

    /// WebSocket close codes. `4401`/`4408`/`4409` are application codes and part
    /// of the contract; `1002`/`1003`/`1009` are the RFC 6455 ones the codec may
    /// send.
    group close as CLOSE {
        AUTH_FAILED: u16 = 4401;
        HELLO_TIMEOUT: u16 = 4408;
        REPLACED: u16 = 4409;
        PROTOCOL_ERROR: u16 = 1002;
        UNSUPPORTED_DATA: u16 = 1003;
        MESSAGE_TOO_BIG: u16 = 1009;
    }
}
